/**
 * IlmuAlam Sitemap - Advanced Blogger Sitemap with Islamic Emoji Mapping
 * 
 * @version 2.0.0
 * @author (IlmuAlam)
 * @license MIT
 * @repository https://github.com/ilmualam/sitemap
 */
const IlmuAlamSitemap = (() => {
  // --- CONFIGURATION ---
  const config = {
    postsPerPage: 16,
    maxFetch: 500, 
    fallbackImg: 'https://via.placeholder.com/600x338?text=Ilmu+Alam'
  };

  // THE MASTER LIST: Only these exact labels will appear as buttons, in this exact order.
  // If you want to add or remove a category from the sitemap, just edit this list.
  const emojiMap = {
    'Semua': '📚', 
    'Islamik': '☪️', 
    'Panduan': '📋', 
    'Al-Quran': '📖', 
    'Al-Quran Interaktif': '💻', 
    'Audio': '🎧', 
    'Belajar Mengaji': '🗣️', 
    'Fadhilat Surah': '✨', 
    'Hafazan': '🎯',
    'Quran Online': '📱', 
    'Rumi': '🔤', 
    'Surah Pilihan': '⭐', 
    'Tafsir': '📚', 
    'Tajwid': '🔊',
    'Tool Interaktif': '🛠️', 
    'Tool Percuma': '🎁',
    'Juz Amma': '📌', 
    'Surah Pendek': '📜', 
    'Solat': '🕌',
    'Ramadan': '🌙',
    'Puasa': '🌅',
    'Hari Raya': '🎉',
    'Haji': '🕋',
    'Kisah Nabi': '👳',
    'Zikir Harian': '📿',
    'Doa': '🤲',
    'Zikir': '📿',
    'Hadis': '📜',
    'Hadith': '📜',
    'Sunnah': '☀️',
    'Fiqh': '⚖️',
    'Akidah': '💎',
    'Waktu Solat': '⏰',
    'Perkahwinan': '💍',
    'Keluarga': '👨‍👩‍👧‍👦',
    'Pendidikan': '🎓',
    'Akhlak': '💚',
    'Adab': '🌹',
    'Kematian': '⚰️',
    'Akhirat': '🌌',
    'Syurga': '🌈',
    'Neraka': '🔥',
    'Doa Harian': '🤲'
 };

  // State Management
  let state = {
    allPosts: [],
    filteredPosts: [],
    labels: Object.keys(emojiMap), // Forces the UI to only use your Master List
    currentLabel: 'Semua',
    currentQuery: '',
    currentPage: 1
  };

  // DOM Elements
  const els = {
    nav: document.getElementById('ilmualam-sitemap-nav'),
    posts: document.getElementById('ilmualam-sitemap-posts'),
    pagination: document.getElementById('ilmualam-sitemap-pagination'),
    search: document.getElementById('ilmualam-sitemap-search')
  };

  // --- CORE ENGINE ---
  const init = async () => {
    els.posts.innerHTML = '<div style="text-align:center; padding:40px; font-weight:bold; color:#0c3802;">Menyusun arkib Ilmu Alam...</div>';
    
    // Bind Search Event Listener
    els.search.addEventListener('input', (e) => {
      state.currentQuery = e.target.value.trim().toLowerCase();
      applyFilters();
    });

    // Start Fetching
    await fetchPosts(1);
    
    // Apply filters immediately after fetching is done
    applyFilters();
  };

  const fetchPosts = async (startIndex) => {
    const url = `/feeds/posts/summary?alt=json&max-results=${config.maxFetch}&start-index=${startIndex}`;
    try {
      const res = await fetch(url);
      const data = await res.json();
      const entries = data.feed.entry || [];
      
      state.allPosts = state.allPosts.concat(entries);

      if (entries.length === config.maxFetch) {
        await fetchPosts(startIndex + config.maxFetch);
      }
    } catch (err) {
      console.error("Sitemap API Error:", err);
      els.posts.innerHTML = '<div style="color:red; text-align:center;">Ralat memuat turun data. Sila muat semula.</div>';
    }
  };

  // --- FILTERING ENGINE ---
  const applyFilters = () => {
    state.currentPage = 1; 
    
    state.filteredPosts = state.allPosts.filter(post => {
      // 1. Check Label Match
      const matchesLabel = state.currentLabel === 'Semua' || 
                           (post.category && post.category.some(cat => cat.term === state.currentLabel));
      
      // 2. Check Search Match
      const matchesSearch = post.title.$t.toLowerCase().includes(state.currentQuery);
      
      return matchesLabel && matchesSearch;
    });

    renderAll();
  };

  const setLabel = (label) => {
    state.currentLabel = label;
    els.search.value = ''; // Clears search bar when clicking a new category
    state.currentQuery = ''; 
    applyFilters();
  };

  // --- RENDERING UI ---
  const renderAll = () => {
    renderNav();
    renderGrid();
    renderPagination();
  };

  const renderNav = () => {
    let html = '<div style="display:flex; flex-wrap:wrap; gap:10px; margin-bottom:25px; justify-content:center;">';
    
    // Directly iterates through your emojiMap keys in the exact order you wrote them
    state.labels.forEach(label => {
      const isActive = label === state.currentLabel;
      const emoji = emojiMap[label];
      
      const bg = isActive ? '#0c3802' : '#fff';
      const color = isActive ? '#fff' : '#0c3802';
      const border = isActive ? '1px solid #0c3802' : '1px solid #c2e0c6';

      html += `<button onclick="IlmuAlamSitemap.setLabel('${label}')" 
                style="background:${bg}; color:${color}; border:${border}; padding:8px 16px; border-radius:20px; cursor:pointer; font-weight:600; font-size:14px; transition:0.3s; display:flex; align-items:center; gap:6px;">
                ${emoji} ${label}
               </button>`;
    });
    
    html += '</div>';
    els.nav.innerHTML = html;
  };

  const renderGrid = () => {
    if (state.filteredPosts.length === 0) {
      els.posts.innerHTML = '<div style="text-align:center; padding:40px; color:#666; font-size:16px;">Tiada artikel dijumpai untuk carian atau kategori ini.</div>';
      return;
    }

    const start = (state.currentPage - 1) * config.postsPerPage;
    const end = start + config.postsPerPage;
    const currentBatch = state.filteredPosts.slice(start, end);

    let html = '<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(300px, 1fr)); gap:20px; margin-bottom:30px;">';

    currentBatch.forEach(post => {
      const title = post.title.$t;
      const linkObj = post.link.find(l => l.rel === 'alternate');
      const url = linkObj ? linkObj.href : '#';
      
      let img = post.media$thumbnail ? post.media$thumbnail.url.replace(/\/s[0-9]+(\-c)?\//, '/w600-h338-p-rw/') : config.fallbackImg;
      
      let snippet = post.summary ? post.summary.$t : '';
      snippet = snippet.replace(/(<([^>]+)>)/gi, "").substring(0, 100) + '...';

      const date = new Date(post.published.$t);
      const formattedDate = date.toLocaleDateString('ms-MY', { day: 'numeric', month: 'short', year: 'numeric' });

      html += `
        <div style="background:#fff; border-radius:12px; overflow:hidden; box-shadow:0 4px 10px rgba(0,0,0,0.05); border:1px solid #eaeaea; display:flex; flex-direction:column;">
          <a href="${url}"><img src="${img}" style="width:100%; aspect-ratio:16/9; object-fit:cover;" alt="${title}" loading="lazy"></a>
          <div style="padding:15px; display:flex; flex-direction:column; flex-grow:1;">
            <a href="${url}" style="text-decoration:none; color:#111;"><h3 style="margin:0 0 10px 0; font-size:18px; line-height:1.4;">${title}</h3></a>
            <p style="color:#666; font-size:14px; margin:0 0 15px 0; line-height:1.5; flex-grow:1;">${snippet}</p>
            <div style="display:flex; justify-content:space-between; align-items:center; border-top:1px solid #f0f0f0; padding-top:12px;">
              <span style="font-size:12px; color:#888;">📅 ${formattedDate}</span>
              <a href="${url}" style="font-size:13px; font-weight:bold; color:#0c3802; text-decoration:none;">Baca Lagi &rarr;</a>
            </div>
          </div>
        </div>
      `;
    });
    
    html += '</div>';
    els.posts.innerHTML = html;
  };

  const renderPagination = () => {
    const totalPages = Math.ceil(state.filteredPosts.length / config.postsPerPage);
    if (totalPages <= 1) {
      els.pagination.innerHTML = '';
      return;
    }

    let html = '<div style="display:flex; justify-content:center; gap:8px; flex-wrap:wrap;">';

    for (let i = 1; i <= totalPages; i++) {
      if (i <= 4 || i === totalPages || (i >= state.currentPage - 1 && i <= state.currentPage + 1)) {
        const isActive = i === state.currentPage;
        const bg = isActive ? '#0c3802' : '#e8f4ea';
        const color = isActive ? '#fff' : '#0c3802';
        
        html += `<button onclick="IlmuAlamSitemap.goToPage(${i})" 
                  style="background:${bg}; color:${color}; border:none; width:40px; height:40px; border-radius:8px; font-weight:bold; cursor:pointer; transition:0.2s;">
                  ${i}
                 </button>`;
      } else if (i === 5 && state.currentPage > 6) {
         html += `<span style="padding:10px;">...</span>`;
      }
    }

    if (state.currentPage < totalPages) {
      html += `<button onclick="IlmuAlamSitemap.goToPage(${state.currentPage + 1})" 
                style="background:#e8f4ea; color:#0c3802; border:none; padding:0 15px; height:40px; border-radius:8px; font-weight:bold; cursor:pointer; transition:0.2s;">
                Seterusnya &rarr;
               </button>`;
    }

    html += '</div>';
    els.pagination.innerHTML = html;
  };

  // --- PUBLIC API ---
  return {
    init: () => {
      if (els.posts) init();
    },
    setLabel: (label) => setLabel(label),
    goToPage: (page) => {
      state.currentPage = page;
      renderGrid();
      renderPagination();
      document.getElementById('ilmualam-sitemap-wrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };
})();

// Ignite the engine
document.addEventListener("DOMContentLoaded", IlmuAlamSitemap.init);
